//! Calendar colours: the 25 calendar colours and, for each, the colours an event block takes. Each
//! colour's tokens, the same in Snow and Carbon, give the swatches and the hover glow's colour. The
//! blocks themselves take Classic's own block colours, which differ from the tokens in Carbon and,
//! where a preview's border is `currentColor`, in Snow.

use egui::Color32;

use crate::{Theme, theme::css_color};

/// One of the calendar colours.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct CalendarColor(usize);

/// Which of a colour's palettes a block takes.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct BlockPalette {
    /// The block is outlined, because I haven't accepted.
    pub unaccepted: bool,
    /// The block is a preview, because a create or edit form is open.
    pub create: bool,
    /// The event has ended.
    pub past: bool,
    /// The event a form makes or changes.
    pub focused: bool,
    /// The block is hovered, its details are open or it's the one being looked at, which gives
    /// a past block brighter colours.
    pub lifted: bool,
}

/// A block's text, fill and border colours.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BlockColors {
    /// `color`.
    pub text: Color32,
    /// `background-color`.
    pub fill: Color32,
    /// `border-color`.
    pub border: Color32,
}

impl CalendarColor {
    /// `blue`, the colour of a calendar with none.
    pub const BLUE: Self = Self(0);

    /// The colour called `name`. `purple`, an old name, is `magenta`.
    pub fn from_name(name: &str) -> Option<Self> {
        let name = if name == "purple" { "magenta" } else { name };
        NAMES
            .iter()
            .position(|candidate| *candidate == name)
            .map(Self)
    }

    /// Every colour, in table order (the order a snap to the nearest one tries them).
    pub fn all() -> impl Iterator<Item = Self> {
        (0..NAMES.len()).map(Self)
    }

    /// The colour picker's order, which is also the order new calendars take unused colours in.
    pub fn picker() -> impl Iterator<Item = Self> {
        PICKER.iter().filter_map(|name| Self::from_name(name))
    }

    /// Its name (`blue`).
    pub fn name(self) -> &'static str {
        NAMES[self.0]
    }

    /// The colour itself, which the hover glow uses.
    pub fn base(self) -> Color32 {
        let [r, g, b] = BASES[self.0];
        Color32::from_rgb(r, g, b)
    }

    /// A block's colours in `theme`: filled, outlined or focused, as a preview or not, past or not,
    /// and lifted when past.
    pub fn block(self, theme: Theme, palette: BlockPalette) -> BlockColors {
        let index = if palette.focused {
            8 + usize::from(palette.past)
        } else if palette.past && palette.lifted {
            10 + usize::from(palette.unaccepted) * 2 + usize::from(palette.create)
        } else {
            usize::from(palette.unaccepted) * 4
                + usize::from(palette.create) * 2
                + usize::from(palette.past)
        };
        let [text, fill, border] =
            CLASSIC_COLOURS[self.0][usize::from(theme == Theme::Carbon)][index];
        BlockColors { text, fill, border }
    }

    /// The glow under a hovered or open block (`:hover`): Snow's `0 0 6px 0 {token}, 0 0 12px 0
    /// {token}/.5`, Carbon's `0 0 6px 1px {fill}/.8, 0 0 12px 1px {fill}/.5` from its filled
    /// block's fill. Returns the near shadow's colour, the far one's, and their spread.
    pub fn glow(self, theme: Theme) -> (Color32, Color32, f32) {
        match theme {
            Theme::Snow => (self.base(), self.base().gamma_multiply(0.5), 0.0),
            Theme::Carbon => {
                let fill = self.block(theme, BlockPalette::default()).fill;
                (fill.gamma_multiply(0.8), fill.gamma_multiply(0.5), 1.0)
            }
        }
    }

    /// A guest's swatch beside their name: the colour itself in Snow, a darker value of its own in
    /// Carbon.
    pub fn guest_swatch(self, theme: Theme) -> Color32 {
        match theme {
            Theme::Snow => self.base(),
            Theme::Carbon => GUEST_SWATCHES_CARBON
                .iter()
                .find(|(name, _)| *name == self.name())
                .map_or_else(|| self.base(), |(_, color)| *color),
        }
    }

    /// The colour's swatch (checkboxes, the details popover's square): its accepted fill.
    pub fn swatch(self, _theme: Theme) -> Color32 {
        self.base()
    }
}

