const fn parse_classic() -> [[[[Color32; 3]; 14]; 2]; 25] {
    let mut out = [[[[Color32::TRANSPARENT; 3]; 14]; 2]; 25];
    let mut row = 0;
    while row < CLASSIC.len() {
        let mut theme = 0;
        while theme < 2 {
            let mut state = 0;
            while state < 14 {
                let mut part = 0;
                while part < 3 {
                    out[row][theme][state][part] = css_color(CLASSIC[row][theme][state][part]);
                    part += 1;
                }
                state += 1;
            }
            theme += 1;
        }
        row += 1;
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_resolve() {
        assert_eq!(
            CalendarColor::from_name("purple"),
            CalendarColor::from_name("magenta")
        );
        assert_eq!(CalendarColor::BLUE.name(), "blue");
        assert_eq!(CalendarColor::picker().count(), 25);
        let blue = CalendarColor::BLUE.block(Theme::Snow, BlockPalette::default());
        assert_eq!(
            (blue.text, blue.fill, blue.border),
            (
                Color32::WHITE,
                Color32::from_rgb(115, 182, 219),
                Color32::WHITE
            )
        );
        assert_eq!(
            CalendarColor::BLUE.swatch(Theme::Carbon),
            CalendarColor::BLUE.base()
        );
    }

    #[test]
    fn swatch_matches_base_for_every_color_and_theme() {
        for color in CalendarColor::all() {
            assert_eq!(color.swatch(Theme::Snow), color.base(), "{}", color.name());
            assert_eq!(
                color.swatch(Theme::Carbon),
                color.base(),
                "{}",
                color.name()
            );
        }
    }

    #[test]
    fn classic_blocks_keep_the_tokens_but_where_classic_differs() {
        // Snow's accepted fill matches the base token; preview borders match their text colour.
        for color in CalendarColor::all() {
            let snow = CLASSIC_COLOURS[color.0][0];
            assert_eq!(
                snow[0][0],
                Color32::WHITE,
                "{} snow filled text",
                color.name()
            );
            assert_eq!(
                snow[0][1],
                color.base(),
                "{} snow filled fill",
                color.name()
            );
            assert_eq!(
                snow[0][2],
                Color32::WHITE,
                "{} snow filled border",
                color.name()
            );
            assert_eq!(
                snow[2][2],
                snow[2][0],
                "{} snow preview border",
                color.name()
            );
            assert_eq!(
                snow[3][2],
                snow[3][0],
                "{} snow past preview border",
                color.name()
            );
            assert_eq!(
                snow[4][1],
                Color32::WHITE,
                "{} snow outlined fill",
                color.name()
            );
            assert_eq!(
                snow[4][2],
                color.base(),
                "{} snow outlined border",
                color.name()
            );
        }
        // Carbon's filled blue is darker than the token (`rgb(99.8, 153.8, 184.2)`).
        assert_eq!(
            CalendarColor::BLUE
                .block(Theme::Carbon, BlockPalette::default())
                .fill,
            Color32::from_rgb(100, 154, 184)
        );
    }

    #[test]
    fn a_lifted_past_block_is_brighter() {
        let past = BlockPalette {
            past: true,
            ..BlockPalette::default()
        };
        let lifted = BlockPalette {
            lifted: true,
            ..past
        };
        let blue = |theme, palette| CalendarColor::BLUE.block(theme, palette);
        assert_eq!(
            blue(Theme::Snow, lifted),
            BlockColors {
                text: Color32::WHITE,
                fill: css_color("rgb(136, 192.95, 224.4)"),
                border: Color32::WHITE,
            }
        );
        assert_eq!(
            blue(Theme::Carbon, lifted).fill,
            css_color("rgb(69.4, 97.4, 114.6)")
        );
        // Lifting does nothing to a block that hasn't ended.
        assert_eq!(
            blue(
                Theme::Snow,
                BlockPalette {
                    lifted: true,
                    ..BlockPalette::default()
                }
            ),
            blue(Theme::Snow, BlockPalette::default())
        );
        assert_ne!(blue(Theme::Snow, lifted), blue(Theme::Snow, past));
    }
}
